/**
 * Responsive image URLs. Uploaded images (/uploads/<file>) have optimised variants
 * generated by the backend:
 *   /media/w{w}/<file>       WebP  (w = 320, 640, 960, 1280, 1920, 2560)
 *   /media/avif/w{w}/<file>  AVIF
 *   /media/w32/<file>        tiny blurred placeholder
 * Unsplash photos (used by the default home-page content) are resized by Unsplash's
 * own image CDN (w / q / auto=format → AVIF or WebP), so they are just as sharp.
 * Anything else (static assets, other external URLs) is used as-is.
 */
export const WIDTHS = [320, 640, 960, 1280, 1920, 2560] as const;
export type ImgFormat = 'webp' | 'avif';

export function isOptimisable(url?: string | null): url is string {
  return !!url && url.startsWith('/uploads/');
}

export function isUnsplash(url?: string | null): boolean {
  return !!url && /^https:\/\/images\.unsplash\.com\//.test(url);
}

function unsplashAt(url: string, w: number): string {
  try {
    const u = new URL(url);
    u.searchParams.set('w', String(w));
    u.searchParams.set('q', w >= 1920 ? '80' : '85');
    u.searchParams.set('auto', 'format');
    u.searchParams.set('fit', 'crop');
    return u.toString();
  } catch {
    return url;
  }
}

function nearestWidth(w: number): number {
  return WIDTHS.find((x) => x >= w) ?? WIDTHS[WIDTHS.length - 1];
}

export function variant(url: string | undefined | null, width = 960, fmt: ImgFormat = 'webp'): string {
  if (!url) return '';
  if (isUnsplash(url)) return unsplashAt(url, nearestWidth(width));
  if (!isOptimisable(url)) return url;
  const file = url.slice('/uploads/'.length);
  const w = nearestWidth(width);
  return fmt === 'avif' ? `/media/avif/w${w}/${file}` : `/media/w${w}/${file}`;
}

export function srcSet(url: string, fmt: ImgFormat = 'webp', widths: readonly number[] = WIDTHS): string {
  if (isUnsplash(url)) return widths.map((w) => `${unsplashAt(url, w)} ${w}w`).join(', ');
  if (!isOptimisable(url)) return '';
  return widths.map((w) => `${variant(url, w, fmt)} ${w}w`).join(', ');
}

export function placeholder(url?: string | null): string | null {
  if (!isOptimisable(url)) return null;
  return `/media/w32/${url.slice('/uploads/'.length)}`;
}

// Matches the format <picture> will choose, so preloads hit the same cache entry.
let avifSupported = false;
if (typeof window !== 'undefined') {
  const probe = new Image();
  probe.onload = () => { avifSupported = probe.width > 0; };
  probe.src =
    'data:image/avif;base64,';
}

/** Warm the browser cache for an image the user is likely to view next. */
const preloaded = new Set<string>();
export function preloadImage(url: string | undefined, width = 1280) {
  if (!url || typeof window === 'undefined') return;
  const href = variant(url, width, avifSupported ? 'avif' : 'webp');
  if (preloaded.has(href)) return;
  preloaded.add(href);
  const img = new Image();
  img.decoding = 'async';
  img.src = href;
}
